const { isApiCredentialAuthMode } = require('../account/runtime-auth-mode');
const { normalizeString } = require('./native-session-chat-utils');

// ── 声明式「provider 错误签名 → 结论」规则表 ────────────────────────────────────────
// 每行声明：命中条件（all = 全部命中；any = 任一命中）+ 结论。新增 provider 错误签名 = 加一行，
// 不改下面的派发代码。命中的第一行胜出（顺序即优先级）。
//
//   kind='turn'     → 影响本轮结果与「换账号重试」
//   kind='blocker'  → 影响账号运行态（把账号摘出调度池）
const PROVIDER_FAILURE_RULES = Object.freeze([
  // Gemini：上游返回 PERMISSION_DENIED（账号无权限）。
  Object.freeze({
    id: 'gemini-permission-denied',
    kind: 'turn',
    provider: 'gemini',
    any: Object.freeze([
      'permission_denied',
      'the caller does not have permission',
      'reason": "forbidden"',
      '"status": "permission_denied"'
    ]),
    code: 'gemini_permission_denied',
    message: '当前 Gemini 账号无权限（PERMISSION_DENIED）',
    retryAnotherAccount: true
  }),
  // cline 额度墙：CLI 打印 "Insufficient balance. Your Cline Credits balance is $0.00"（2026-10-15 实测）。
  Object.freeze({
    id: 'cline-insufficient-credits',
    kind: 'turn',
    provider: 'cline',
    all: Object.freeze(['insufficient balance']),
    any: Object.freeze(['cline credits', 'balance is $0']),
    code: 'cline_insufficient_credits',
    message: '当前 Cline 账号额度不足（Cline Credits 余额为 0），请换账号或充值',
    retryAnotherAccount: true
  }),
  // Antigravity 地区/资格拒用（2026-10-15 实测：`Eligibility check failed: Your current account is
  // not eligible for Antigravity, because it is not currently available in your location.`）。
  // 这不是凭据失效也不是限流：账号本身在当前地区不可用 → 换账号重试 + 把该账号摘出调度池。
  Object.freeze({
    id: 'agy-region-not-eligible',
    kind: 'turn',
    provider: 'agy',
    all: Object.freeze(['eligibility check failed']),
    code: 'agy_region_not_eligible',
    message: '该 agy 账号在当前地区不可用（Antigravity 地区资格限制），请换账号或调整出口',
    retryAnotherAccount: true
  }),
  Object.freeze({
    id: 'agy-region-not-eligible-blocker',
    kind: 'blocker',
    provider: 'agy',
    all: Object.freeze(['eligibility check failed']),
    status: 'permission_denied',
    reason: 'agy_region_not_eligible',
    buildState: buildPermissionDeniedRuntimeState
  })
]);

function matchesRule(rule, lowered) {
  const all = Array.isArray(rule.all) ? rule.all : [];
  const any = Array.isArray(rule.any) ? rule.any : [];
  if (all.some((pattern) => !lowered.includes(String(pattern).toLowerCase()))) return false;
  if (any.length > 0 && !any.some((pattern) => lowered.includes(String(pattern).toLowerCase()))) return false;
  return all.length > 0 || any.length > 0;
}

function findProviderRule(kind, provider, lowered) {
  return PROVIDER_FAILURE_RULES.find((rule) => (
    rule.kind === kind && rule.provider === provider && matchesRule(rule, lowered)
  )) || null;
}

function stripAnsi(text) {
  return String(text || '').replace(/[\u001b\u009b][[()#;?]*(?:[0-9]{1,4}(?:;[0-9]{0,4})*)?[0-9A-ORZcf-nqry=><]/g, '');
}


function sanitizeTerminalText(text) {
  return stripAnsi(String(text || ''))
    .replace(/\u0000/g, '')
    .replace(/[^\S\r\n\t]+$/gm, '');
}


function classifyNativeSessionFailure(provider, errorLike, options = {}) {
  const normalizedProvider = normalizeString(provider).toLowerCase();
  const sourceCode = normalizeString(errorLike && errorLike.code);
  const text = normalizeString(
    (errorLike && errorLike.message)
    || errorLike
    || ''
  );
  const lowered = text.toLowerCase();

  // provider 专属错误签名：查声明式规则表（新增签名 = 加一行，不动这里）。
  const rule = findProviderRule('turn', normalizedProvider, lowered);
  if (rule) {
    return {
      code: rule.code,
      message: rule.message,
      retryAnotherAccount: rule.retryAnotherAccount === true
    };
  }

  return {
    code: sourceCode || 'native_session_failed',
    message: text || (
      Number.isFinite(Number(options.exitCode))
        ? `native_session_failed_exit_${Number(options.exitCode)}`
        : 'native_session_failed'
    ),
    retryAnotherAccount: false
  };
}


function classifyNativeAccountRuntimeBlocker(provider, outputLike) {
  const normalizedProvider = normalizeString(provider).toLowerCase();
  const plain = sanitizeTerminalText(String(outputLike || '')).replace(/\s+/g, ' ').trim();
  if (!plain) return null;
  const lowered = plain.toLowerCase();

  // provider 专属运行态阻塞：声明式规则表（新增签名 = 加一行）。
  const blockerRule = findProviderRule('blocker', normalizedProvider, lowered);
  if (blockerRule) {
    return {
      provider: normalizedProvider,
      status: blockerRule.status,
      reason: blockerRule.reason,
      source: 'native_session_terminal_output',
      runtimeState: blockerRule.buildState(blockerRule.reason),
      message: plain.slice(0, 512)
    };
  }

  // 「401」必须是独立的状态码（不能是「14012 tokens」里的子串），旁证也必须是认证语义本身：
  // 旧规则用 'auth' / 'token' 当旁证，会命中 OAuth、author、tokens —— 任何恰好输出了这些词的
  // 非零退出（包括被看门狗杀掉、用户取消的会话）都会被判成凭据失效。
  const looksUnauthorized = /\b401\b/.test(lowered)
    && /unauthori[sz]ed|unauthenticated|authentication|incorrect api key|invalid[ _-]?(?:api[ _-]?key|token|credentials?)|token (?:has )?expired|expired[ _-]token/.test(lowered);
  const looksApiKeyInvalid = lowered.includes('incorrect api key')
    || lowered.includes('invalid api key')
    || lowered.includes('invalid_api_key')
    || lowered.includes('api key provided');
  // 不认 aih 自己的 `auth_invalid_reauth_required`：那是 aih 网关「整池不可调度」的信封码，
  // 说明 CLI 连的是一台 aih 网关、对端池子没号了，与本账号的凭据无关
  // （HTTP 侧同一信封由 isRelayPoolAuthExhaustedResponse 识别，这里保持同一口径）。
  const looksRefreshInvalid = lowered.includes('token_expired')
    || lowered.includes('invalid_grant')
    || lowered.includes('your session has expired')
    || lowered.includes('re-authentication required')
    || lowered.includes('provided authentication token is expired')
    || lowered.includes('access token could not be refreshed')
    || lowered.includes('refresh token') && (
      lowered.includes('expired')
      || lowered.includes('invalid')
      || lowered.includes('reused')
    );
  const looksClaudeLoginMissing = normalizedProvider === 'claude'
    && (
      lowered.includes('authentication_failed')
      || lowered.includes('not logged in') && lowered.includes('/login')
      || lowered.includes('please run /login')
    );
  // "not signed in" 只是 antigravity CLI 的冷启动横幅（紧跟着 "Signing in..." 用 token 自动登录，
  // 冷启动可达~100s）。之前一看到它就判 auth_invalid + kill 进程 → 账号明明正常却被premature 打成
  // 未登录并熔断。真正的失败信号是自动登录失败后 CLI 回退到交互式「select login method」。
  const looksAgyLoginMissing = normalizedProvider === 'agy'
    && lowered.includes('select login method')
    && lowered.includes('google oauth');

  if (looksApiKeyInvalid || looksUnauthorized || looksRefreshInvalid || looksClaudeLoginMissing || looksAgyLoginMissing) {
    const reason = looksApiKeyInvalid || looksUnauthorized
      ? 'upstream_401'
      : looksClaudeLoginMissing
        ? 'claude_not_logged_in'
      : looksAgyLoginMissing
        ? 'agy_not_signed_in'
      : 'auth_invalid_reauth_required';
    return {
      provider: normalizedProvider,
      status: 'auth_invalid',
      reason,
      source: 'native_session_terminal_output',
      runtimeState: buildAuthInvalidRuntimeState(reason),
      message: plain.slice(0, 512)
    };
  }

  return null;
}


function recordNativeAccountRuntimeBlocker(options = {}, blocker = null) {
  const provider = normalizeString(options.provider || blocker && blocker.provider).toLowerCase();
  const accountRef = normalizeString(options.accountRef);
  if (!provider || !accountRef || !blocker || !blocker.runtimeState) return false;
  const baseState = buildNativeAccountRuntimeBaseState(options, provider, accountRef);
  const event = {
    provider,
    accountRef,
    previousStatus: 'unknown',
    nextStatus: blocker.status || 'auth_invalid',
    reason: blocker.reason || 'auth_invalid_reauth_required',
    source: blocker.source || 'native_session_terminal_output',
    runtimeState: blocker.runtimeState,
    baseState
  };
  // 运行态变更统一走门禁（见 account-runtime-gate 的 observeRuntimeState）；未装配时退回
  // 直接发事件 / 直调服务（单测与降级装配）。
  const gate = options.accountRuntimeGate;
  if (gate && typeof gate.observeRuntimeState === 'function') {
    return gate.observeRuntimeState({
      provider,
      accountRef,
      runtimeState: blocker.runtimeState,
      baseState: event.baseState,
      nextStatus: event.nextStatus,
      reason: event.reason,
      source: event.source
    });
  }
  const hub = options.accountRuntimeEventHub || options.hub;
  let hubPersisted = false;
  if (hub && typeof hub.emit === 'function') {
    const results = hub.emit(ACCOUNT_RUNTIME_CHANGED, event);
    hubPersisted = results === true || (Array.isArray(results) && results[0] === true);
  }
  if (hubPersisted) return true;
  const service = options.accountStateService;
  if (service && typeof service.recordRuntimeFailure === 'function') {
    return service.recordRuntimeFailure(accountRef, provider, blocker.runtimeState, event.baseState);
  }
  return false;
}


function buildNativeAccountRuntimeBaseState(options, provider, accountRef) {
  let authMode = normalizeString(options.authMode || options.identityKind).toLowerCase();
  const aiHomeDir = normalizeString(options.aiHomeDir);
  if (!authMode && aiHomeDir) {
    try {
      authMode = detectIdentityKind({ fs, aiHomeDir, provider, accountRef });
    } catch (_error) {
      authMode = '';
    }
  }
  const baseState = {
    configured: true
  };
  if (authMode) {
    baseState.authMode = authMode;
    baseState.apiKeyMode = isApiCredentialAuthMode(authMode);
  }
  return baseState;
}


function hasActiveNativeAccountRuntimeBlock(options, accountRef, happenedAt) {
  const service = options.accountStateService;
  if (!service || typeof service.getAccountState !== 'function') return true;
  try {
    const accountState = service.getAccountState(accountRef);
    const runtimeState = accountState && accountState.runtimeState;
    const lastFailureAt = Number(runtimeState && runtimeState.lastFailureAt) || 0;
    return Boolean(
      runtimeState
      && lastFailureAt <= happenedAt
      && deriveAccountRuntimeStatus({ ...runtimeState }).status !== 'healthy'
    );
  } catch (_error) {
    return true;
  }
}


function recordNativeAccountRuntimeSuccess(options = {}) {
  const provider = normalizeString(options.provider).toLowerCase();
  const accountRef = normalizeString(options.accountRef);
  if (!provider || !accountRef) return false;
  const now = Date.now();
  const reportedAt = Number(options.happenedAt);
  const happenedAt = Number.isFinite(reportedAt) && reportedAt > 0
    ? Math.min(reportedAt, now)
    : now;
  if (!hasActiveNativeAccountRuntimeBlock(options, accountRef, happenedAt)) return false;
  const baseState = buildNativeAccountRuntimeBaseState(options, provider, accountRef);
  const event = {
    provider,
    accountRef,
    previousStatus: 'unknown',
    nextStatus: 'healthy',
    reason: 'native_session_success',
    source: normalizeString(options.source) || 'native_session',
    runtimeState: null,
    baseState,
    happenedAt
  };
  // 运行态恢复统一走门禁（见 account-runtime-gate 的 observeRecovery）；未装配门禁时退回
  // 直接发事件 / 直调服务（单测与降级装配）。
  const gate = options.accountRuntimeGate;
  if (gate && typeof gate.observeRecovery === 'function') {
    return gate.observeRecovery({
      account: { accountRef, provider },
      provider,
      evidence: 'native_session_success',
      baseState,
      clear: 'account',
      source: normalizeString(options.source) || 'native_session'
    });
  }
  const hub = options.accountRuntimeEventHub || options.hub;
  let hubPersisted = false;
  if (hub && typeof hub.emit === 'function') {
    const results = hub.emit(ACCOUNT_RUNTIME_CHANGED, event);
    hubPersisted = results === true || (Array.isArray(results) && results[0] === true);
  }
  if (hubPersisted) return true;
  const service = options.accountStateService;
  if (service && typeof service.recordRuntimeSuccess === 'function') {
    return service.recordRuntimeSuccess(accountRef, provider, {
      ...baseState,
      evidence: 'native_session_success'
    });
  }
  if (service && typeof service.clearRuntimeBlock === 'function') {
    return service.clearRuntimeBlock(accountRef, provider, {
      ...baseState,
      evidence: 'native_session_success'
    });
  }
  return false;
}


function shouldScanNativeRuntimeBlockerOutput(context = {}) {
  if (context.interactiveCli === true) return true;
  if (context.explicitError === true) return true;
  const exitCode = Number(context.exitCode);
  return Number.isFinite(exitCode) && exitCode !== 0;
}


module.exports = { stripAnsi, sanitizeTerminalText, classifyNativeSessionFailure, classifyNativeAccountRuntimeBlocker, recordNativeAccountRuntimeBlocker, buildNativeAccountRuntimeBaseState, hasActiveNativeAccountRuntimeBlock, recordNativeAccountRuntimeSuccess, shouldScanNativeRuntimeBlockerOutput };
